        ax = abs(x - ox)
        ay = abs(y - oy)
        return ax if ax > ay else ay

    def man(x, y):
        return abs(x - ox) + abs(y - oy)

    def dist(x, y):
        ax = abs(x - ox)
        ay = abs(y - oy)
        return (ax * ax + ay * ay)

    def obstacle_adjacency(x, y):
        c = 0
        for dx in (-1, 0, 1):
            for dy in (-1, 0, 1):
                if dx == 0 and dy == 0:
                    continue
                nx, ny = x + dx, y + dy
                if (nx, ny) in blocked:
                    c += 1
        return c

    best = None
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            nx, ny = sx + dx, sy + dy
            if not (0 <= nx < w and 0 <= ny < h):
                continue
            if (nx, ny) in blocked:
                continue
            c = cheb(nx, ny)
            m = man(nx, ny)
            d = dist(nx, ny)
            adj = obstacle_adjacency(nx, ny)
            if is_evader:
                key = (-c, -m, -d, adj, dx, dy)
            else:
                key = (c, m, d, -adj, dx, dy)
            if best is None or key < best[0]:
                best = (key, dx, dy)

    if best is None:
